"""Command-line interface."""

import argparse
import sys
from pathlib import Path
from typing import List, Optional

from .industry_data import IndustryData
from .invention import InventionData, InventionError, InventionPlanner, render_invention
from .inventory import Inventory
from .item_info import describe
from .plan import BuildPlanner, PlanError, load_config, write_plan
from .recipe import MAX_MATERIAL_EFFICIENCY, MAX_TIME_EFFICIENCY, RecipeError, RecipeResolver
from .report import render
from .sde_loader import SDEFileError


def _material_efficiency(value: str) -> int:
    try:
        me = int(value)
    except ValueError:
        raise argparse.ArgumentTypeError(f"invalid integer: {value!r}")
    if not 0 <= me <= MAX_MATERIAL_EFFICIENCY:
        raise argparse.ArgumentTypeError(
            f"must be an integer in [0,{MAX_MATERIAL_EFFICIENCY}], got {me}"
        )
    return me


def _time_efficiency(value: str) -> int:
    try:
        te = int(value)
    except ValueError:
        raise argparse.ArgumentTypeError(f"invalid integer: {value!r}")
    if not 0 <= te <= MAX_TIME_EFFICIENCY or te % 2:
        raise argparse.ArgumentTypeError(
            f"must be an even integer in [0,{MAX_TIME_EFFICIENCY}], got {te}"
        )
    return te


def build_parser() -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(
        prog="industry.py",
        description="Plan EVE Online industry builds from the Static Data Export.",
    )
    sub = parser.add_subparsers(dest="command", required=True)
    recipe = sub.add_parser("recipe", help="Show the recipe for a product or blueprint")
    recipe.add_argument("name", nargs="+", help="Exact typeName of a product or blueprint")
    recipe.add_argument("--sde", required=True, help="Path to the SDE directory")
    recipe.add_argument("--material-efficiency", "-me", dest="me", type=_material_efficiency,
                        default=0, metavar="ME",
                        help="Blueprint material efficiency, integer in [0,10] (default 0)")
    recipe.add_argument("--time-efficiency", "-te", dest="te", type=_time_efficiency,
                        default=0, metavar="TE",
                        help="Blueprint time efficiency, even integer in [0,20] (default 0)")
    recipe.add_argument("--display-waste", "-waste", dest="waste", action="store_true",
                        help="Show material wasted compared to ME 10")
    invention = sub.add_parser("invention", help="Plan invention / reverse engineering for a product")
    invention.add_argument("name", nargs="+", help="Exact typeName of a Tech II/III product or blueprint")
    invention.add_argument("--sde", required=True, help="Path to the SDE directory")
    invention.add_argument("--skill", type=int, default=5, choices=range(1, 6), metavar="{1-5}",
                           help="Level used for all relevant skills (default 5)")
    plan = sub.add_parser("plan", help="Create a build plan (jobs.csv, materials.csv) for an item")
    plan.add_argument("name", nargs="+", help="Build string, e.g. 'Barrage L 10 None x10'")
    plan.add_argument("--config", required=True, help="YAML build config file")
    plan.add_argument("--sde", required=True, help="Path to the SDE directory")
    plan.add_argument("--output", required=True, help="Directory to write the CSV files to")
    return parser


def run_recipe(name: str, sde_dir: Path, me: int = 0, te: int = 0, waste: bool = False) -> str:
    inventory = Inventory(sde_dir)
    published = {t.type_id for t in inventory.types.values() if t.published}
    industry = IndustryData(sde_dir, published)
    recipe = RecipeResolver(inventory, industry).resolve(name, me=me, te=te)
    return render(describe(inventory, recipe.product), recipe, show_waste=waste)


def run_invention(name: str, sde_dir: Path, skill: int) -> str:
    inventory = Inventory(sde_dir)
    published = {t.type_id for t in inventory.types.values() if t.published}
    industry = IndustryData(sde_dir, published)
    invention = InventionData(sde_dir, published)
    plan = InventionPlanner(inventory, industry, invention).plan(name, skill)
    return render_invention(describe(inventory, plan.product), plan)


def run_plan(build: str, config_path: Path, sde_dir: Path, output_dir: Path) -> None:
    config = load_config(config_path)
    inventory = Inventory(sde_dir)
    published = {t.type_id for t in inventory.types.values() if t.published}
    industry = IndustryData(sde_dir, published)
    invention = InventionData(sde_dir, published)
    planner = BuildPlanner(inventory, industry, invention)
    plan = planner.plan(planner.parse(build), config)
    write_plan(plan, inventory, output_dir)


def main(argv: Optional[List[str]] = None) -> int:
    args = build_parser().parse_args(argv)
    name = " ".join(args.name)
    sde_dir = Path(args.sde)
    if not sde_dir.is_dir():
        print(f"Error: SDE directory not found: {sde_dir}", file=sys.stderr)
        return 2
    try:
        if args.command == "recipe":
            print(run_recipe(name, sde_dir, args.me, args.te, args.waste))
        elif args.command == "invention":
            print(run_invention(name, sde_dir, args.skill))
        elif args.command == "plan":
            run_plan(name, Path(args.config), sde_dir, Path(args.output))
        else:
            return 2
    except (RecipeError, InventionError, PlanError, SDEFileError) as exc:
        print(f"Error: {exc}", file=sys.stderr)
        return 1
    return 0
"""Build plans: parses a build string and produces the jobs and materials to buy."""

import csv
import math
import re
from collections import defaultdict
from dataclasses import dataclass, field
from pathlib import Path
from typing import Dict, List, Optional, Tuple

from . import constants as C
from .industry_data import ActivityKey, IndustryData
from .invention import DECRYPTORS, InventionData, InventionError, InventionPlanner
from .inventory import Inventory
from .models import InvType
from .recipe import MAX_MATERIAL_EFFICIENCY, MAX_TIME_EFFICIENCY
from .sde_loader import load_yaml

MAX_TE_BONUS = 30
SECONDS_PER_DAY = 86400
NO_DECRYPTOR = "None"
DECRYPTOR_SUFFIX = " Decryptor"

_JOBS_RE = re.compile(r"^[xX](\d+)$")
_INT_RE = re.compile(r"^\d+$")


class PlanError(Exception):
    """Raised when a build string or config cannot be turned into a build plan."""


@dataclass(frozen=True)
class PlanConfig:
    te_bonus: int = 0
    invention_skill: int = 5


@dataclass(frozen=True)
class BuildSpec:
    product: InvType
    blueprint_key: ActivityKey
    runs: int
    jobs: int
    me: int = 0
    te: int = 0
    decryptor: Optional[str] = None  # set for invention / reverse engineering
    relic: Optional[str] = None  # set for reverse engineering

    @property
    def invented(self) -> bool:
        return self.decryptor is not None


@dataclass(frozen=True)
class Job:
    name: str
    runs: int
    days: float
    count: int


@dataclass
class BuildPlan:
    jobs: List[Job] = field(default_factory=list)
    # typeID -> quantity to buy
    purchases: Dict[int, int] = field(default_factory=dict)


def load_config(path: Path) -> PlanConfig:
    if not path.is_file():
        raise PlanError(f"Config file not found: {path}")
    raw = load_yaml(path.parent, path.name)
    if not isinstance(raw, dict):
        raise PlanError(f"Config file must be a mapping: {path}")
    te_bonus = _config_int(raw, "te_bonus", 0, 0, MAX_TE_BONUS)
    skill = _config_int(raw, "invention_skill", 5, 1, 5)
    return PlanConfig(te_bonus=te_bonus, invention_skill=skill)


def _config_int(raw: dict, key: str, default: int, low: int, high: int) -> int:
    value = raw.get(key, default)
    if value is None:
        value = default
    if isinstance(value, bool) or not isinstance(value, (int, float)) or int(value) != value:
        raise PlanError(f"Config '{key}' must be an integer in [{low},{high}], got {value!r}")
    value = int(value)
    if not low <= value <= high:
        raise PlanError(f"Config '{key}' must be an integer in [{low},{high}], got {value}")
    return value


def _decryptor_name(text: str) -> Optional[str]:
    """Canonical decryptor name ('None' included) for user text, or None if unknown."""
    folded = text.lower()
    for name, *_ in DECRYPTORS:
        if folded == name.lower():
            return name
        if name.endswith(DECRYPTOR_SUFFIX) and folded == name[: -len(DECRYPTOR_SUFFIX)].lower():
            return name
    return None


def _positive(text: str, what: str) -> int:
    value = int(text)
    if value < 1:
        raise PlanError(f"{what} must be at least 1, got {value}")
    return value


class BuildPlanner:
    def __init__(self, inventory: Inventory, industry: IndustryData, invention: InventionData):
        self.inventory = inventory
        self.industry = industry
        self.invention = invention

    # --- build string parsing ----------------------------------------------

    def parse(self, build: str) -> BuildSpec:
        tokens = build.split()
        if not tokens:
            raise PlanError("Empty build string")
        jobs = 1
        match = _JOBS_RE.match(tokens[-1])
        if match and len(tokens) > 1:
            jobs = _positive(match.group(1), "Number of jobs")
            tokens = tokens[:-1]

        # Longest item name first, so names containing numbers still resolve.
        for split in range(len(tokens), 0, -1):
            name = " ".join(tokens[:split])
            target = self._production_key(name)
            if target is None:
                continue
            spec = self._interpret(target, tokens[split:], jobs)
            if spec is not None:
                return spec

        for split in range(len(tokens), 0, -1):
            if self.inventory.published_by_name(" ".join(tokens[:split])):
                raise PlanError(f"Cannot interpret build string '{build}'")
        raise PlanError(f"No buildable published item found in build string '{build}'")

    def _production_key(self, name: str) -> Optional[Tuple[InvType, ActivityKey]]:
        candidates = self.inventory.published_by_name(name)
        for item in candidates:
            sources = self.industry.sources_of(item.type_id)
            if sources:
                return item, sources[0]
        # Be lenient and accept a blueprint name as well.
        for item in candidates:
            key = self.industry.blueprint_activity(item.type_id)
            if key is not None:
                product = self.inventory.types.get(self.industry.products[key][0][0])
                if product is not None:
                    return product, key
        return None

    def _interpret(self, target: Tuple[InvType, ActivityKey], rest: List[str],
                   jobs: int) -> Optional[BuildSpec]:
        product, key = target
        if not rest:
            return BuildSpec(product, key, runs=1, jobs=jobs)
        if not _INT_RE.match(rest[0]):
            return None
        runs = _positive(rest[0], "Runs per job")
        rest = rest[1:]
        if not rest:
            return BuildSpec(product, key, runs=runs, jobs=jobs)
        if len(rest) == 2 and all(_INT_RE.match(t) for t in rest):
            me, te = int(rest[0]), int(rest[1])
            if not 0 <= me <= MAX_MATERIAL_EFFICIENCY:
                raise PlanError(f"Material efficiency must be in [0,{MAX_MATERIAL_EFFICIENCY}], got {me}")
            if not 0 <= te <= MAX_TIME_EFFICIENCY:
                raise PlanError(f"Time efficiency must be in [0,{MAX_TIME_EFFICIENCY}], got {te}")
            return BuildSpec(product, key, runs=runs, jobs=jobs, me=me, te=te)
        for split in range(len(rest), 0, -1):
            decryptor = _decryptor_name(" ".join(rest[:split]))
            if decryptor is None:
                continue
            relic = " ".join(rest[split:]) or None
            return BuildSpec(product, key, runs=runs, jobs=jobs, decryptor=decryptor, relic=relic)
        return None

    # --- planning ----------------------------------------------------------

    def plan(self, spec: BuildSpec, config: PlanConfig) -> BuildPlan:
        purchases: Dict[int, int] = defaultdict(int)
        me, te = spec.me, spec.te
        if spec.invented:
            me, te = self._plan_invention(spec, config, purchases)

        blueprint_id, activity_id = spec.blueprint_key
        if activity_id != C.MANUFACTURING:
            me = te = 0

        for material_id, qty in self.industry.materials.get(spec.blueprint_key, {}).items():
            per_job = max(spec.runs, -(-qty * (100 - me) * spec.runs // 100))
            purchases[material_id] += per_job * spec.jobs

        seconds = self.industry.times.get(spec.blueprint_key, 0) * spec.runs
        seconds *= (100 - te) * (100 - config.te_bonus) / 10000
        job = Job(
            name=self.inventory.type_name(blueprint_id),
            runs=spec.runs,
            days=round(seconds / SECONDS_PER_DAY, 2),
            count=spec.jobs,
        )
        return BuildPlan(jobs=[job], purchases=dict(purchases))

    def _plan_invention(self, spec: BuildSpec, config: PlanConfig,
                        purchases: Dict[int, int]) -> Tuple[int, int]:
        """Add invention inputs to ``purchases``; return the invented blueprint's (ME, TE)."""
        planner = InventionPlanner(self.inventory, self.industry, self.invention)
        try:
            invention = planner.plan(spec.product.name, config.invention_skill)
        except InventionError as exc:
            raise PlanError(str(exc))
        is_t3 = invention.tech_level == "Tech III"
        if is_t3 and spec.relic is None:
            raise PlanError(f"'{spec.product.name}' is reverse engineered; a relic name is required")
        if not is_t3 and spec.relic is not None:
            raise PlanError(f"'{spec.product.name}' is invented; relics do not apply")

        row = next(
            (r for r in invention.rows
             if r.decryptor == spec.decryptor and (not is_t3 or r.invented_from == spec.relic)),
            None,
        )
        if row is None:
            raise PlanError(f"'{spec.relic}' cannot be used to reverse engineer '{spec.product.name}'")
        if row.probability <= 0 or row.runs <= 0:
            raise PlanError(f"'{spec.product.name}' cannot be invented with these inputs")

        blueprints = math.ceil(spec.runs * spec.jobs / row.runs)
        attempts = math.ceil(blueprints / row.probability - 1e-9)

        source = self._invention_source(spec, is_t3)
        for material_id, qty in self.invention.materials.get(source, {}).items():
            purchases[material_id] += qty * attempts
        if spec.decryptor != NO_DECRYPTOR:
            purchases[self._type_id(spec.decryptor)] += attempts
        if is_t3:
            purchases[source[0]] += attempts
        return row.me, row.te

    def _invention_source(self, spec: BuildSpec, is_t3: bool) -> ActivityKey:
        sources = self.invention.sources_of(spec.blueprint_key[0])
        if is_t3:
            for key in sources:
                if self.inventory.type_name(key[0]) == spec.relic:
                    return key
            raise PlanError(f"'{spec.relic}' cannot be used to reverse engineer '{spec.product.name}'")
        return sources[0]

    def _type_id(self, name: str) -> int:
        candidates = self.inventory.published_by_name(name)
        if not candidates:
            raise PlanError(f"No published item named '{name}' found in the SDE")
        return candidates[0].type_id


# --- output ----------------------------------------------------------------

def write_plan(plan: BuildPlan, inventory: Inventory, output_dir: Path) -> None:
    output_dir.mkdir(parents=True, exist_ok=True)

    rows = []
    for type_id, quantity in plan.purchases.items():
        item = inventory.types.get(type_id)
        name = inventory.type_name(type_id)
        volume = inventory.packaged_volume(item) if item else 0.0
        rows.append((name, quantity, round(quantity * volume, 2), 0, 0))
    rows.sort(key=lambda r: r[0])
    with open(output_dir / "materials.csv", "w", newline="", encoding="utf-8") as fh:
        writer = csv.writer(fh, lineterminator="\n")
        writer.writerow(["name", "to_buy", "buy_volume", "start_amount", "end_amount"])
        writer.writerows(rows)

    jobs = sorted(plan.jobs, key=lambda j: (j.name, j.runs, j.count, j.days))
    with open(output_dir / "jobs.csv", "w", newline="", encoding="utf-8") as fh:
        writer = csv.writer(fh, lineterminator="\n")
        writer.writerow(["name", "runs", "days", "count"])
        for job in jobs:
            writer.writerow([job.name, job.runs, job.days, job.count])

"""Item, group, category, market group and meta (tech level) data."""

from collections import defaultdict
from pathlib import Path
from typing import Dict, List, Optional

from . import constants as C
from .models import Group, InvType, MarketGroup
from .sde_loader import iter_csv, load_yaml, parse_float, parse_int


class Inventory:
    """Indexes the inv* tables and ship volumes from the SDE."""

    def __init__(self, sde_dir: Path):
        self.types: Dict[int, InvType] = {}
        self.types_by_name: Dict[str, List[InvType]] = defaultdict(list)
        self.groups: Dict[int, Group] = {}
        self.categories: Dict[int, str] = {}
        self.market_groups: Dict[int, MarketGroup] = {}
        self.meta_group_of_type: Dict[int, int] = {}
        self.meta_group_names: Dict[int, str] = {}
        self.ship_volumes: Dict[str, float] = {}
        self._load(sde_dir)

    def _load(self, sde_dir: Path) -> None:
        for row in iter_csv(sde_dir, C.INV_TYPES):
            item = InvType(
                type_id=int(row["typeID"]),
                group_id=parse_int(row["groupID"]),
                name=row["typeName"],
                volume=parse_float(row["volume"]),
                published=parse_int(row["published"]) == 1,
                market_group_id=parse_int(row["marketGroupID"]),
            )
            self.types[item.type_id] = item
            if item.published:
                self.types_by_name[item.name].append(item)

        for row in iter_csv(sde_dir, C.INV_GROUPS):
            group = Group(
                group_id=int(row["groupID"]),
                category_id=parse_int(row["categoryID"]),
                name=row["groupName"],
            )
            self.groups[group.group_id] = group

        for row in iter_csv(sde_dir, C.INV_CATEGORIES):
            self.categories[int(row["categoryID"])] = row["categoryName"]

        for row in iter_csv(sde_dir, C.INV_MARKET_GROUPS):
            mg = MarketGroup(
                market_group_id=int(row["marketGroupID"]),
                parent_id=parse_int(row["parentGroupID"]),
                name=row["marketGroupName"],
            )
            self.market_groups[mg.market_group_id] = mg

        for row in iter_csv(sde_dir, C.INV_META_TYPES):
            meta_id = parse_int(row["metaGroupID"])
            if meta_id is not None:
                self.meta_group_of_type[int(row["typeID"])] = meta_id

        for row in iter_csv(sde_dir, C.INV_META_GROUPS):
            self.meta_group_names[int(row["metaGroupID"])] = row["metaGroupName"]

        raw_volumes = load_yaml(sde_dir, C.SHIP_VOLUMES)
        self.ship_volumes = {str(k): float(v) for k, v in raw_volumes.items()}

    # --- lookups -----------------------------------------------------------

    def published_by_name(self, name: str) -> List[InvType]:
        """All published types whose name matches exactly (case-sensitive)."""
        return sorted(self.types_by_name.get(name, []), key=lambda t: t.type_id)

    def type_name(self, type_id: int) -> str:
        item = self.types.get(type_id)
        return item.name if item else str(type_id)

    def group_of(self, item: InvType) -> Optional[Group]:
        return self.groups.get(item.group_id)

    def category_name_of(self, item: InvType) -> str:
        group = self.group_of(item)
        if group is None:
            return "Unknown"
        return self.categories.get(group.category_id, "Unknown")

    def group_name_of(self, item: InvType) -> str:
        group = self.group_of(item)
        return group.name if group else "Unknown"

    def market_group_path(self, item: InvType) -> Optional[List[str]]:
        """Market group names from root to leaf, or None if not on the market."""
        if item.market_group_id is None:
            return None
        path: List[str] = []
        seen = set()
        current = self.market_groups.get(item.market_group_id)
        while current is not None and current.market_group_id not in seen:
            seen.add(current.market_group_id)
            path.append(current.name)
            if current.parent_id is None:
                break
            current = self.market_groups.get(current.parent_id)
        if not path:
            return None
        path.reverse()
        return path

    def tech_level_of(self, item: InvType) -> str:
        meta_id = self.meta_group_of_type.get(item.type_id)
        meta_name = self.meta_group_names.get(meta_id, "") if meta_id else ""
        for level in C.TECH_LEVELS:
            if meta_name == level or meta_name.endswith(" " + level):
                return level
        return C.DEFAULT_TECH_LEVEL

    def is_ship(self, item: InvType) -> bool:
        return self.category_name_of(item) == C.SHIP_CATEGORY_NAME

    def packaged_volume(self, item: InvType) -> float:
        """Packaged volume: ship_volumes.yaml for ships, invTypes otherwise."""
        if self.is_ship(item):
            group_name = self.group_name_of(item)
            if group_name in self.ship_volumes:
                return self.ship_volumes[group_name]
        return item.volume
